window.DECKS.push({"slug":"obgyn1","name":"Obgyn 1","folder":"OBGYN 1","questions":[
{"id":"og1-01","p":8,"stem":"Perempuan G1P0A0 memeriksakan kehamilan; lupa HPHT. Tinggi fundus uteri setinggi umbilikus. Perkiraan usia kehamilan adalah…","opts":["17 minggu","21 minggu","25 minggu","19 minggu","15 minggu"],"ans":1,"why":"TFU setinggi pusat ≈ 20–22 minggu (catatan dosen). Patokan: 12 minggu = 3 jari di atas simfisis, 16 minggu = pertengahan simfisis-pusat, 20–22 minggu = pusat, 28 minggu = 3 jari di atas pusat, 36 minggu = processus xiphoideus.","ref":[6,7],"tags":["ANC","TFU"],"skdi":"4A","src":"coretan","cards":[{"q":"TFU setinggi pusat = usia kehamilan?","a":"± 20–22 minggu"},{"q":"TFU setinggi processus xiphoideus?","a":"± 36 minggu"}]},
{"id":"og1-02","p":8,"stem":"Perempuan terlambat haid ±2 bulan, ingin memastikan apakah hamil. Manakah yang merupakan tanda PROBABLE (kemungkinan) kehamilan?","opts":["DJJ (+)","Kantong gestasi pada USG","Amenore","β-hCG (+)","Rasa kencang pada payudara"],"ans":3,"why":"Tanda pasti: DJJ, gerak janin, kantong gestasi/janin pada USG. Tanda kemungkinan (probable): tes β-hCG/plano (+), Hegar, Chadwick, Goodell, Piskacek, ballotement. Tanda dugaan (presumptif): amenore, mual, payudara tegang.","ref":[6],"tags":["Tanda kehamilan"],"skdi":"4A","src":"coretan","cards":[{"q":"Plano test (+): tanda pasti, kemungkinan, atau dugaan?","a":"Kemungkinan (probable)"},{"q":"Amenore: tanda pasti, kemungkinan, atau dugaan?","a":"Dugaan (presumptif)"},{"q":"DJJ (+): tanda pasti, kemungkinan, atau dugaan?","a":"Pasti"}]},
{"id":"og1-03","p":8,"stem":"Perempuan terlambat haid ±2 bulan; dokter melakukan pemeriksaan fisik. Yang BUKAN tanda probable kehamilan pada pemeriksaan fisik adalah…","opts":["Turtle sign","Hegar sign","Chadwick sign","Goodell sign","Hartman sign"],"ans":0,"why":"Turtle sign adalah tanda distosia bahu (kepala tertarik kembali ke perineum), bukan tanda kehamilan. Hegar (istmus lunak), Chadwick (vagina/serviks kebiruan), Goodell (serviks lunak), dan Hartman (perdarahan implantasi) termasuk tanda kehamilan.","ref":[6],"tags":["Tanda kehamilan"],"skdi":"4A","src":"coretan","cards":[{"q":"Hegar sign?","a":"Istmus uteri melunak"},{"q":"Chadwick sign?","a":"Vagina/serviks kebiruan"},{"q":"Goodell sign?","a":"Serviks melunak"},{"q":"Turtle sign menandakan…?","a":"Distosia bahu"},{"q":"Hartman sign?","a":"Perdarahan implantasi blastula"},{"q":"Tanda presumtif kehamilan dinilai dari…?","a":"Anamnesis"},{"q":"Contoh tanda presumtif kehamilan?","a":"Amenore, mual muntah, payudara kencang"},{"q":"Tanda probable kehamilan dinilai dari…?","a":"Pemeriksaan fisik (+ β-hCG)"},{"q":"Contoh tanda probable kehamilan?","a":"Chadwick, Goodell, Hegar, Hartman, linea nigra, β-hCG +"},{"q":"Contoh tanda definitif (pasti) kehamilan?","a":"Kantong gestasi di USG, DJJ, gerakan janin"},{"q":"DJJ dengan Doppler terdengar mulai UK?","a":"12 minggu"},{"q":"DJJ dengan Laennec terdengar mulai UK?","a":"17–18 minggu"},{"q":"Gerakan janin (tanda pasti) teraba mulai UK?","a":"> 16 minggu"}]},
{"id":"og1-04","p":8,"stem":"Wanita 20 tahun G1P0A0 hamil 36 minggu ANC. Pelvimetri: diameter AP = transversal. Jenis panggulnya adalah…","opts":["Android","Ginekoid","Platipeloid","Antropoid","Pelvikoid"],"ans":1,"why":"Kunci dosen: AP = TV adalah ginekoid (bentuk bulat, terbaik untuk persalinan). Antropoid: AP > TV. Platipeloid: TV > AP. Android: berbentuk jantung (segitiga).","ref":[5],"tags":["Panggul"],"skdi":"4A","src":"coretan","cards":[{"q":"Panggul antropoid?","a":"Diameter AP > transversal"},{"q":"Panggul platipeloid?","a":"Transversal > AP (gepeng)"},{"q":"Panggul android?","a":"Berbentuk jantung/segitiga"}]},
{"id":"og1-05","p":13,"stem":"Wanita 23 tahun G2P1A0 hamil 12 minggu ANC, tanpa keluhan. Riwayat anak lahir tanpa tempurung kepala (anensefali). Nutrisi yang tepat untuk mencegah kondisi serupa adalah…","opts":["Asam folat 4 mcg","Asam folat 40 mcg","Asam folat 400 mcg","Asam folat 4000 mcg","Asam folat 40000 mcg"],"ans":3,"why":"Riwayat anak dengan defek tabung saraf (risiko tinggi): asam folat dosis TINGGI 4 mg (4000 mcg)/hari, mulai sebelum konsepsi. Populasi umum: 400 mcg/hari.","ref":[12],"tags":["ANC","Asam folat"],"skdi":"4A","src":"coretan","cards":[{"q":"Asam folat untuk ibu hamil risiko rendah?","a":"400 mcg/hari"},{"q":"Asam folat bila riwayat anak NTD?","a":"4 mg (4000 mcg)/hari"}]},
{"id":"og1-06","p":13,"stem":"Wanita 23 tahun G1P0A0 hamil 28 minggu. Leopold I: teraba 2 ballotement; Leopold II dan III: banyak bagian kecil. Diagnosis yang tepat adalah…","opts":["Janin tunggal letak lintang","Janin tunggal letak memanjang","Gemelli letak memanjang","Gemelli letak lintang","Janin tunggal presentasi bokong"],"ans":2,"why":"Dua bagian bulat yang melenting (ballotement = kepala) di fundus dan banyak bagian kecil menunjukkan dua janin (gemelli). Kepala di fundus berarti sumbu janin searah sumbu ibu, jadi letak memanjang.","ref":[9,10,11],"tags":["Leopold","Gemelli"],"skdi":"4A","src":"coretan","cards":[{"q":"Ballotement pada Leopold menandakan bagian…?","a":"Kepala janin"}]},
{"id":"og1-07","p":13,"stem":"Perempuan G1P0A0 hamil 6 minggu belum pernah vaksin tetanus; dokter memberi TT1 hari itu. Pada usia kehamilan berapa TT3 diberikan?","opts":["30 minggu","32 minggu","34 minggu","36 minggu","38 minggu"],"ans":2,"why":"Jadwal TT: TT2 ≥ 4 minggu setelah TT1, TT3 ≥ 6 bulan setelah TT2. TT1 di minggu 6, TT2 di ±minggu 10, TT3 6 bulan kemudian ≈ minggu 34 (perhitungan dosen).","ref":[12],"tags":["Imunisasi TT"],"skdi":"4A","src":"coretan","cards":[{"q":"Interval TT1 → TT2?","a":"≥ 4 minggu"},{"q":"Interval TT2 → TT3?","a":"≥ 6 bulan"},{"q":"Interval TT3 → TT4 → TT5?","a":"≥ 1 tahun masing-masing"}]},
{"id":"og1-08","p":13,"stem":"Wanita 23 tahun G1P0A0 hamil 34 minggu. Leopold I: bulat keras; Leopold II: bulat lunak; Leopold III: bagian kecil janin. Diagnosis yang tepat adalah…","opts":["Tunggal, letak lintang, presentasi kepala","Tunggal, letak memanjang, presentasi kepala","Tunggal, letak memanjang, presentasi bokong","Tunggal, letak lintang, presentasi bokong","Tunggal, letak memanjang, presentasi dagu"],"ans":2,"why":"Bulat keras (kepala) di FUNDUS berarti bagian terendah adalah bokong: letak memanjang, presentasi bokong. Bagian kecil teraba di Leopold III (ekstremitas) sesuai presentasi bokong.","ref":[9,10,11],"tags":["Leopold"],"skdi":"4A","src":"coretan","cards":[{"q":"Leopold I menilai…?","a":"Bagian janin di fundus"},{"q":"Leopold III menilai…?","a":"Bagian terendah janin (presentasi)"}]},
{"id":"og1-09","p":22,"stem":"Perempuan 23 tahun G2P1A0 hamil 37 minggu, keluar air-air dari jalan lahir 2 jam, mulas. VT: teraba bokong, pembukaan 5 cm. Yang diperiksa pada pasien 4 jam kemudian adalah…","opts":["Tekanan darah","Suhu","Pembukaan serviks","Penurunan janin","Semua pilihan benar"],"ans":4,"why":"Partograf kala I fase aktif: tekanan darah, VT (pembukaan dan penurunan) tiap 4 jam; suhu tiap 2–4 jam (lebih sering bila ketuban pecah); DJJ, his, dan nadi tiap 30 menit. Semuanya dinilai saat evaluasi 4 jam.","ref":[16,19],"tags":["Partograf"],"skdi":"4A","src":"coretan","cards":[{"q":"Partograf: VT diperiksa tiap…?","a":"4 jam"},{"q":"Partograf: DJJ, his, nadi tiap…?","a":"30 menit"},{"q":"Partograf: tekanan darah tiap…?","a":"4 jam"}]},
{"id":"og1-10","p":22,"stem":"Perempuan 31 tahun G2P1A0 hamil 37 minggu, mulas 3 jam; VT: teraba bokong, pembukaan 10 cm. Dokter memimpin persalinan hingga bayi lahir. Langkah selanjutnya adalah…","opts":["Membersihkan sisa plasenta","Manual plasenta","Masase uterus","Peregangan tali pusat terkendali","Injeksi oksitosin"],"ans":4,"why":"Manajemen aktif kala III, urutannya: (1) suntik oksitosin 10 IU IM dalam 1 menit setelah bayi lahir (setelah memastikan tidak ada janin kedua), (2) PTT, (3) masase fundus.","ref":[17],"tags":["MAK III"],"skdi":"4A","src":"coretan","cards":[{"q":"Langkah pertama MAK III?","a":"Oksitosin 10 IU IM dalam 1 menit"},{"q":"Urutan MAK III?","a":"Oksitosin → PTT → masase fundus"}]},
{"id":"og1-11","p":22,"stem":"Wanita 21 tahun G1P0A0 hamil 39–40 minggu, bayi lahir spontan. Dokter melakukan peregangan tali pusat terkendali dengan tangan kiri di atas simfisis pubis (dorsokranial). Perasat yang digunakan adalah…","opts":["Perasat Kustner","Perasat Hegar","Perasat Brandt-Andrews","Perasat McRoberts","Perasat Credé"],"ans":2,"why":"PTT dengan tangan lain menekan uterus ke arah dorsokranial di atas simfisis adalah perasat Brandt-Andrews. Kustner: menekan di atas simfisis untuk menilai apakah plasenta sudah lepas (tali pusat tidak masuk kembali). Credé: memeras fundus (berbahaya, risiko inversio).","ref":[17,38,39],"tags":["Kala III","Perasat"],"skdi":"4A","src":"coretan","cards":[{"q":"Perasat Brandt-Andrews?","a":"PTT + tekan uterus dorsokranial"},{"q":"Perasat Kustner?","a":"Menilai pelepasan plasenta (tekan atas simfisis)"},{"q":"Bahaya perasat Credé?","a":"Inversio uteri"}]},
{"id":"og1-12","p":22,"stem":"Perempuan 28 tahun P1A0, 4 hari pascapersalinan, keluar darah dari jalan lahir tanpa demam. Tanda vital normal, lokia rubra, TFU 1 jari di bawah umbilikus. Diagnosis yang tepat adalah…","opts":["Atonia uteri","Subinvolusi uteri","Prolaps uteri","Sisa plasenta","Endometritis"],"ans":1,"why":"Normalnya pada hari ke-4 TFU sudah turun ke sekitar pertengahan pusat-simfisis. TFU yang masih 1 jari di bawah pusat dengan perdarahan (lokia rubra memanjang) adalah subinvolusi uteri. TFU 1 jari di bawah pusat adalah posisi normal tepat setelah bayi lahir.","ref":[20,21],"tags":["Nifas"],"skdi":"3A","src":"coretan","cards":[{"q":"TFU 1 minggu pascasalin?","a":"Pertengahan pusat-simfisis"},{"q":"Lokia rubra berlangsung…?","a":"Hari 1–3/4"}]},
{"id":"og1-13","p":36,"stem":"Wanita 31 tahun G1P0A0 hamil 37–38 minggu, kencang-kencang sejak semalam, lendir darah. Pembukaan 7 cm. Setelah observasi 4 jam, kepala bayi belum turun. Diagnosis yang tepat adalah…","opts":["Inpartu kala I fase laten memanjang","Inpartu kala I fase aktif memanjang","Inpartu kala II memanjang","Inpartu kala III memanjang","Inpartu kala IV memanjang"],"ans":1,"why":"Pembukaan ≥ 4 cm adalah fase aktif. Kemajuan yang terhenti dalam 4 jam (melewati garis waspada partograf) adalah kala I fase aktif memanjang. Fase laten memanjang: pembukaan < 4 cm lebih dari 8 jam.","ref":[29,30],"tags":["Persalinan lama"],"skdi":"3B","src":"coretan","cards":[{"q":"Fase laten memanjang?","a":"Pembukaan < 4 cm > 8 jam"},{"q":"Kala II memanjang primigravida?","a":"> 2 jam"},{"q":"Kala II memanjang multigravida?","a":"> 1 jam"}]},
{"id":"og1-14","p":36,"stem":"Wanita 21 tahun G1P0A0 hamil 39 minggu dirujuk bidan: kepala bayi sudah lahir tetapi bahu tertahan di simfisis. Kemungkinan etiologinya adalah…","opts":["Disproporsi kepala panggul","Gangguan his","Distosia bahu","Malpresentasi","Inersia uteri"],"ans":2,"why":"Bahu anterior tertahan di belakang simfisis setelah kepala lahir (turtle sign) adalah distosia bahu. Manuver pertama: McRoberts + tekanan suprapubik.","ref":[34,35],"tags":["Distosia bahu"],"skdi":"3B","src":"coretan","cards":[{"q":"Manuver pertama distosia bahu?","a":"McRoberts + tekanan suprapubik"}]},
{"id":"og1-15","p":36,"stem":"Wanita 27 tahun G1P0A0 hamil 41 minggu ANC rutin, belum mulas, tanpa tanda inpartu. DJJ 124, ketuban intak. Tatalaksana yang tepat adalah…","opts":["Pimpin persalinan","Induksi persalinan","Rencanakan seksio sesarea","Bantu persalinan dengan vakum","Observasi"],"ans":1,"why":"Kunci dosen: kehamilan ≥ 41 minggu (lewat waktu) belum inpartu dengan janin baik → induksi persalinan untuk mencegah komplikasi postterm. SC hanya bila ada indikasi.","ref":[27,31],"tags":["Postterm","Induksi"],"skdi":"3B","src":"coretan","cards":[{"q":"Kehamilan postterm = usia…?","a":"≥ 42 minggu"}]},
{"id":"og1-16","p":36,"stem":"Wanita 24 tahun G2P1A0 hamil 40 minggu kencang-kencang; setelah observasi 2 jam bayi tidak lahir. Pembukaan lengkap, presentasi belakang kepala, kepala di Hodge III, ibu masih bisa meneran. Tatalaksana yang tepat adalah…","opts":["Pimpin persalinan","Induksi oksitosin","Rencanakan seksio sesarea","Bantu persalinan dengan vakum","Bantu persalinan dengan forsep"],"ans":3,"why":"Kala II memanjang (multigravida > 1 jam) dengan kepala sudah rendah (Hodge III+) dan ibu masih bisa meneran → ekstraksi VAKUM (perlu kerja sama meneran ibu). Forsep dipilih bila ibu kelelahan atau tidak boleh meneran. (Catatan dosen.)","ref":[29,32],"tags":["Kala II memanjang","Vakum"],"skdi":"3A","src":"coretan","cards":[{"q":"Vakum vs forsep: kapan forsep?","a":"Ibu lelah/tidak boleh meneran"},{"q":"Syarat kepala untuk vakum?","a":"Minimal Hodge III"}]},
{"id":"og1-17","p":40,"stem":"Perempuan 32 tahun G1P0A0 hamil 37 minggu, keluar air-air 1 jam, mulas. VT: teraba DAHI, pembukaan 3 cm. Tatalaksana yang paling tepat adalah…","opts":["Mulai persalinan pervaginam","Induksi","Rencana SC","Tokolitik","Observasi"],"ans":2,"why":"Presentasi dahi menghasilkan diameter terbesar (mentooksipital ±13,5 cm) sehingga tidak dapat lahir pervaginam pada janin aterm (bila tidak berubah menjadi muka atau belakang kepala) → seksio sesarea.","ref":[37],"tags":["Malpresentasi"],"skdi":"3A","src":"coretan","cards":[{"q":"Presentasi dahi aterm: tatalaksana?","a":"Seksio sesarea"}]},
{"id":"og1-18","p":40,"stem":"Wanita 23 tahun G2P1A0 kencang-kencang, lendir darah. Leopold I: keras; II: punggung kanan; III: lunak. Pemeriksaan dalam: teraba ekstremitas yang TIDAK dapat menggenggam. Presentasi janinnya adalah…","opts":["Presentasi verteks","Presentasi bokong","Presentasi kaki","Presentasi bahu","Presentasi dahi"],"ans":2,"why":"Kepala di fundus (Leopold I keras) berarti presentasi bokong/kaki. Ekstremitas yang tidak bisa menggenggam (ada tumit, jari pendek sejajar) adalah KAKI; tangan bisa menggenggam. Jadi presentasi kaki.","ref":[37],"tags":["Malpresentasi"],"skdi":"3A","src":"coretan","cards":[{"q":"Membedakan tangan vs kaki saat VT?","a":"Tangan menggenggam; kaki ada tumit, tidak menggenggam"}]},
{"id":"og1-19","p":40,"stem":"Perempuan 28 tahun G1P0A0 hamil 38 minggu, keluar air-air, mulas; VT: teraba bokong. Dokter dan bidan memulai persalinan. Perasat untuk melahirkan BAHU janin pada kasus ini adalah…","opts":["Lovset","Pinard","Wood-screw","Rubin","Brandt-Andrews"],"ans":0,"why":"Persalinan sungsang: lengan dan bahu dilahirkan dengan Lovset (memutar badan janin 180°) atau Müller/klasik. Kepala dilahirkan dengan Mauriceau. Pinard untuk menurunkan kaki pada bokong murni. Wood-screw dan Rubin untuk distosia bahu presentasi kepala.","ref":[38,39],"tags":["Persalinan sungsang","Perasat"],"skdi":"3A","src":"coretan","cards":[{"q":"Sungsang: perasat melahirkan bahu/lengan?","a":"Lovset (atau Müller, klasik)"},{"q":"Sungsang: perasat melahirkan kepala?","a":"Mauriceau"},{"q":"Sungsang spontan seluruhnya: perasat?","a":"Bracht"}]},
{"id":"og1-20","p":40,"stem":"Perempuan 24 tahun G1P0A0 hamil 39 minggu, keluar air-air, mulas 8 jam. VT: teraba satu kaki, pembukaan 10 cm. RS terdekat 5 jam; persalinan dimulai di puskesmas. Perasat untuk melahirkan janin adalah…","opts":["Müller","Pinard","Bracht","Wood-screw","Rubin"],"ans":2,"why":"Persalinan sungsang (kaki) pervaginam spontan, dengan rujukan tidak memungkinkan, dibantu perasat BRACHT (janin dipegang dan diangkat ke arah perut ibu tanpa tarikan).","ref":[38,39],"tags":["Persalinan sungsang"],"skdi":"3A","src":"coretan","cards":[]},
{"id":"og1-21","p":46,"stem":"Wanita 27 tahun P2A0, 1 jam postpartum, perdarahan dari jalan lahir dengan nyeri hebat; riwayat SC pada anak pertama. Plasenta lahir lengkap 30 menit setelah bayi, tanpa laserasi, kontraksi uterus sulit dinilai. Diagnosis yang tepat adalah…","opts":["Atonia uteri","Ruptur uteri","Retensio plasenta","Inversio uteri","Sisa plasenta"],"ans":1,"why":"Riwayat SC (parut uterus) dengan perdarahan, NYERI HEBAT, dan uterus sulit diraba/dinilai mengarah ke ruptur uteri. Atonia: uterus lembek tanpa nyeri hebat.","ref":[42,43,44],"tags":["HPP","Ruptur uteri"],"skdi":"3A","src":"coretan","cards":[{"q":"Faktor risiko utama ruptur uteri?","a":"Riwayat SC/parut uterus"}]},
{"id":"og1-22","p":46,"stem":"Wanita 35 tahun G2P1A0 hamil 35 minggu, perdarahan dari jalan lahir sejak semalam, lemas, nyeri perut. Uterus tegang, DJJ tidak terdengar. USG: hematoma retroplasenta. Diagnosis yang tepat adalah…","opts":["Plasenta previa","Plasenta perkreta","Abruptio plasenta","Vasa previa","Abortus"],"ans":2,"why":"Perdarahan antepartum yang NYERI dengan uterus tegang (woody uterus), gawat janin atau janin mati, dan hematoma retroplasenta adalah solusio (abruptio) plasenta. Plasenta previa: perdarahan tanpa nyeri, darah segar, uterus lemas.","ref":[44,45],"tags":["HAP","Solusio plasenta"],"skdi":"3B","src":"coretan","cards":[{"q":"Solusio plasenta: nyeri?","a":"Nyeri + uterus tegang"},{"q":"Plasenta previa: nyeri?","a":"Tidak nyeri"}]},
{"id":"og1-23","p":46,"stem":"Wanita 30 tahun G2P1A0 baru melahirkan normal, perdarahan dari jalan lahir. Setelah 30 menit plasenta belum lahir walaupun PTT sudah dilakukan. Tatalaksana yang tepat adalah…","opts":["Histerektomi","Manual plasenta","Injeksi oksitosin","Masase uterus","Rujuk"],"ans":1,"why":"Retensio plasenta (> 30 menit setelah bayi lahir) yang disertai perdarahan → plasenta manual (dengan oksitosin drip dan antibiotik profilaksis).","ref":[42,44],"tags":["HPP","Retensio plasenta"],"skdi":"4A","src":"coretan","cards":[{"q":"Retensio plasenta = plasenta belum lahir setelah…?","a":"30 menit"}]},
{"id":"og1-24","p":46,"stem":"Wanita 22 tahun P1A0, 1 jam postpartum, dirujuk bidan karena perdarahan; sudah 30 menit plasenta tidak lahir. Tatalaksana yang tepat adalah…","opts":["PTT","Histerektomi","PTT + drip oksitosin","Manual plasenta + drip oksitosin","Antibiotik IV"],"ans":3,"why":"Retensio plasenta dengan perdarahan → plasenta manual + oksitosin drip (20 IU dalam 500 mL) untuk kontraksi, ditambah antibiotik profilaksis.","ref":[42,44],"tags":["HPP","Retensio plasenta"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og1-25","p":53,"stem":"Wanita G1P0A0 hamil 16 minggu, perdarahan dari jalan lahir sejak semalam, nyeri perut. Bercak darah, tanpa gumpalan, OUE TERTUTUP. Diagnosis yang tepat adalah…","opts":["Abortus iminens","Abortus insipiens","Abortus komplet","Abortus inkomplet","Abortus habitualis"],"ans":0,"why":"Perdarahan sedikit dengan OUE TERTUTUP, tanpa jaringan keluar, janin masih hidup adalah abortus iminens (mengancam). Terapi: tirah baring, ± progesteron.","ref":[48,49],"tags":["Abortus"],"skdi":"3B","src":"coretan","cards":[{"q":"Abortus iminens: OUE?","a":"Tertutup"},{"q":"Abortus insipiens: OUE & jaringan?","a":"Terbuka, jaringan belum keluar"},{"q":"Abortus inkomplet: OUE & jaringan?","a":"Terbuka, sebagian jaringan keluar"}]},
{"id":"og1-26","p":53,"stem":"Wanita 23 tahun G1P0A0 hamil 16 minggu, keluar darah dari jalan lahir sejak semalam, nyeri perut bawah; gumpalan jaringan disangkal. Bercak darah, tanpa gumpalan, OUE TERBUKA. Diagnosis yang tepat adalah…","opts":["Abortus iminens","Abortus insipiens","Abortus komplet","Abortus inkomplet","Abortus habitualis"],"ans":1,"why":"OUE TERBUKA tetapi belum ada jaringan yang keluar adalah abortus insipiens (sedang berlangsung, tidak dapat dipertahankan). Terapinya evakuasi (kuretase).","ref":[48,49],"tags":["Abortus"],"skdi":"3B","src":"coretan","cards":[{"q":"Abortus habitualis?","a":"Abortus spontan ≥ 3× berturut-turut"}]},
{"id":"og1-27","p":53,"stem":"Wanita 28 tahun G1P0A0 UK 16 minggu, nyeri perut bawah dan perdarahan dari jalan lahir. Lemah, anemis, TD 90/60, N 90. Nyeri goyang serviks (+), kuldosentesis (+). Diagnosis yang tepat adalah…","opts":["Abortus","PID","Mola hidatidosa","Kehamilan ektopik","Kehamilan ektopik terganggu"],"ans":4,"why":"Nyeri perut, perdarahan, tanda syok/anemia, nyeri goyang serviks (chandelier sign), dan kuldosentesis (+) (darah tidak membeku di kavum Douglas) adalah kehamilan ektopik TERGANGGU (ruptur) → laparotomi segera.","ref":[51,52],"tags":["KET"],"skdi":"3B","src":"coretan","cards":[{"q":"Kuldosentesis (+) pada KET berarti…?","a":"Darah tidak membeku di kavum Douglas"}]},
{"id":"og1-28","p":53,"stem":"Wanita 25 tahun G1P0A0 hamil 14 minggu, perdarahan dari jalan lahir 1 hari, mual muntah; keluar jaringan dan nyeri perut disangkal. Plano test (–). USG seperti pada gambar (gambaran snowstorm/vesikuler). Diagnosis yang tepat adalah…","opts":["Abortus","Mola hidatidosa","Kehamilan ektopik","Kehamilan ektopik terganggu","Plasenta previa"],"ans":1,"why":"Gambaran snowstorm (honeycomb/vesikuler) pada USG dengan perdarahan dan hiperemesis adalah mola hidatidosa (komplet). Catatan: plano 'negatif' bisa terjadi pada kadar hCG sangat tinggi (hook effect). Terapinya evakuasi (kuret isap) dan follow-up β-hCG.","ref":[50,52],"tags":["Mola hidatidosa"],"skdi":"3A","src":"coretan","img":true,"cards":[{"q":"Gambaran USG mola hidatidosa?","a":"Snowstorm / vesikuler"},{"q":"Follow-up setelah evakuasi mola?","a":"Serial β-hCG"}]},
{"id":"og1-x01","lat":"pj-int2","ln":13,"lp":5,"stem":"Wanita berusia 33 tahun dengan G2P1A0 dengan usia kehamilan 8 minggu datang ke Puskesmas untuk mengkonsultasikan kehamilannya. Sebelumnya pasien pernah melahirkan anak yang meninggal setelah dilahirkan dengan anensefali. Untuk itu pasien datang agar kejadian tersebut tidak terulang kembali pada kehamilan saat ini. Pemeriksaan fisik dalam batas normal dan status obstetric dalam batas normal. Bagaimanakah edukasi yang tepat?","opts":["Perbanyak minum teh","Perbanyak konsumsi asam folat","Perbanyak asupan vitamin C","Perbanyak konsumsi serat","Perbanyak konsumsi kopi"],"ans":1,"why":"Riwayat anak anensefali (defek tabung saraf) → suplementasi asam folat. Untuk risiko tinggi (riwayat NTD) dosis 4 mg/hari, idealnya mulai sebelum konsepsi sampai trimester I.","ref":[10,11],"tags":["Antenatal care","Asam folat"],"skdi":"4A","src":"kunci","cards":[{"q":"Pencegahan defek tabung saraf?","a":"Asam folat"},{"q":"Asam folat pada riwayat NTD: dosis?","a":"4 mg/hari"}]},
{"id":"og1-x02","lat":"pj-obg","ln":1,"lp":2,"stem":"Seorang wanita usia 29 tahun pasca melahirkan anak pertamanya 1 jam yang lalu secara per vaginam. Saat ini perdarahan tidak kunjung berhenti. Pemeriksaan tanda vital tekanan darah pasien 80/50, HR 122, RR 22, suhu afebris. Pemeriksaan fisik menunjukkan adanya laserasi perineum derajat 1 dan robekan pada portio arah jam 8. Apakah tatalaksana awal pada pasien?","opts":["Massase uterus","Tampon vagina","Asam traneksamat","Jahit perineum","Resusitasi cairan intravena"],"ans":4,"why":"HPP dengan syok (TD 80/50, HR 122) akibat robekan jalan lahir (portio). Prinsip: resusitasi cairan IV/ABC dulu, baru atasi sumber (jahit robekan). Massase uterus untuk atonia.","ref":[41,42],"tags":["Perdarahan postpartum"],"skdi":"4A","src":"kunci","cards":[{"q":"HPP disertai syok: langkah pertama?","a":"Resusitasi cairan IV (ABC)"},{"q":"4T penyebab HPP?","a":"Tone, Trauma, Tissue, Thrombin"}]},
{"id":"og1-x03","lat":"pj-obg","ln":2,"lp":2,"stem":"Seorang wanita usia 21 tahun G1P0A0 usia kehamilan 12 minggu datang ke IGD RS dengan keluhan keluar darah dari jalan lahir sejak 3 jam SMRS. Keluhan nyeri perut maupun keluar jaringan disangkal. Pada pemeriksaan fisik didapatkan TTV TD 120/80, HR 102, RR 22, T 37. TFU setinggi umbilicus. Inspekulo tampak OUE tertutup dan perdarahan aktif keluar dari OUE. Dokter memutuskan untuk melanjutkan pemeriksaan USG. Apakah gambaran yang dijumpai pada pemeriksaan USG?","opts":["End line","Honeycomb appearance","Swiss cheese appearance","Air fluid level","Batwing appearance"],"ans":1,"why":"Perdarahan pada kehamilan muda dengan TFU lebih besar dari usia kehamilan (12 minggu, TFU setinggi pusat) → mola hidatidosa. USG: honeycomb / snowstorm appearance, tanpa janin (mola komplit).","ref":[50],"tags":["Mola hidatidosa"],"skdi":"3B","src":"kunci","cards":[{"q":"USG mola hidatidosa?","a":"Honeycomb / snowstorm appearance"},{"q":"Mola: TFU dibanding usia kehamilan?","a":"Lebih besar"}]},
{"id":"og1-x04","lat":"pj-obg","ln":3,"lp":2,"stem":"Seorang wanita 21 tahun datang dengan keluhan keluar darah seperti menstruasi 2 jam yang lalu disertai nyeri perut. Darah yang keluar dikatakan disertai dengan gumpalan darah seperti jaringan. Pasien mengatakan sedang hamil 2 15 minggu. Pada saat pemeriksaan didapatkan PP test (-), serviks tertutup. tidak teraba jaringan, TFU tidak teraba Apakah diagnosis yang paling tepat?","opts":["Abortus inkomplit","Abortus komplit","Abortus iminens","Abortus insipient","Missed abortus"],"ans":1,"why":"Perdarahan dengan keluar jaringan, serviks sudah TERTUTUP, uterus tidak teraba/kecil, PP test (−) → abortus komplit (seluruh hasil konsepsi keluar). Inkomplit: serviks terbuka, sisa jaringan.","ref":[48,49],"tags":["Abortus"],"skdi":"4A","src":"kunci","cards":[{"q":"Abortus komplit: OUE?","a":"Tertutup, jaringan sudah keluar semua"},{"q":"Abortus inkomplit: OUE?","a":"Terbuka, sisa jaringan"},{"q":"Abortus insipiens: OUE?","a":"Terbuka, jaringan belum keluar"}]},
{"id":"og1-x05","lat":"pj-obg","ln":4,"lp":2,"stem":"Seorang wanita usia 22 tahun datang ke poliklinik kandungan karena telat haid disertai mual dan muntah dalam 1 minggu terakhir. Pada pemeriksaan inspekulo didapatkan cervix berwarna keunguan dan didapatkan perlunakan pada segmen bawah rahim. Plano test (+). Pemeriksaan USG ditemukan gestasional sac dengan perkiraan usia kehamilan Minggu. Yang merupakan tanda presumtif kehamilan pada pasien tersebut adalah?","opts":["Gestasional sac","Cervix berwarna keunguan","Perlunakan pada segmen bawah rahim","Mual dan muntah","Plano test (+)"],"ans":3,"why":"Tanda PRESUMTIF (dugaan, subjektif): amenore, mual-muntah, payudara tegang, sering BAK, quickening. Tanda TIDAK PASTI (kemungkinan): Chadwick (serviks keunguan), Hegar (SBR lunak), Goodell, Piskacek, tes hCG (+). Tanda PASTI: DJJ, gerak janin diraba pemeriksa, janin/kantong gestasi di USG.","ref":[6],"tags":["Tanda kehamilan"],"skdi":"4A","src":"kunci","cards":[{"q":"Contoh tanda presumtif kehamilan?","a":"Amenore, mual-muntah"},{"q":"Contoh tanda kemungkinan (tidak pasti) kehamilan?","a":"Chadwick, Hegar, tes hCG +"},{"q":"Contoh tanda pasti kehamilan?","a":"DJJ, janin/GS di USG"},{"q":"Tanda Chadwick?","a":"Serviks/vagina kebiruan-keunguan"},{"q":"Tanda Hegar?","a":"Perlunakan segmen bawah rahim"}]},
{"id":"og1-x06","lat":"pj-obg","ln":5,"lp":2,"stem":"Seorang wanita 24 tahun G1P0A0 usia kehamilan 40 mimggu dirujuk ke RS oleh puskesmas karena partus tak maju. TFU diantara umbilicus dan processus xypoideus. Dari riwayat ANC, TBJ 2800 gram. Pemeriksaan His 3-4 kali selama 45 detik dalam 10 menit. Pemeriksaan dalam didapatkan pembukaan 7 cm dan teraba spina ischiadica. Apakah penyebab partus tak maju pada kasus diatas?","opts":["Pintu atas panggul sempit","Pintu tengah panggul sempit","Makrosomia","His lemah","Pintu bawah panggul sempit"],"ans":1,"why":"His adekuat, TBJ 2800 g (bukan makrosomia), tetapi spina iskiadika menonjol/teraba → kesempitan PINTU TENGAH panggul (bidang sempit, diameter interspinarum). Pintu atas: promontorium teraba (konjugata diagonalis pendek).","ref":[5,29],"tags":["Partus tak maju","Pelvimetri"],"skdi":"3A","src":"kunci","cards":[{"q":"Spina iskiadika teraba menonjol → kesempitan…?","a":"Pintu tengah panggul"},{"q":"Promontorium teraba → kesempitan…?","a":"Pintu atas panggul"}]},
{"id":"og1-x07","lat":"pj-obg","ln":7,"lp":3,"stem":"Wanita 34 tahun G2P1A0 hamil 30 minggu datang dengan keluhan keluar darah dari jalan lahir sejak 2 jam yang lalu. Darah segar keluar sedikit-sedikit, tidak nyeri. Keluhan serupa saat usia kehamilan 24 minggu dan berhenti sendiri. Pasien seorang perokok. Riwayat trauma disangkal. Pemeriksaan tanda vital dalam batas normal. DJJ 135 kali/menit. Apakah diagnosis kasus diatas?","opts":["Solusio plasenta","Abruptio plasenta","Placenta previa","Placenta akreta","Vasa previa"],"ans":2,"why":"Perdarahan antepartum darah segar, TANPA nyeri, berulang (sebelumnya pada 24 minggu), DJJ baik → plasenta previa. Solusio: nyeri + uterus tegang, darah kehitaman. JANGAN periksa dalam (VT).","ref":[45,47],"tags":["Plasenta previa"],"skdi":"3B","src":"kunci","cards":[{"q":"Plasenta previa: periksa dalam boleh?","a":"Tidak (kontraindikasi VT)"}]},
{"id":"og1-x08","lat":"pj-obg","ln":8,"lp":3,"stem":"Seorang pasien 29 tahun G2P1A0 UK 38-39 minggu datang ke puskesmas dengan keluhan kenceng-kenceng sejak 6 jam yang lalu. Keluhan disertai cairan jenrih dan lender darah dari jalan lahir. Pemeriksaan vital sign TD 130/70, HR 77, RR 20, T 36.9. DJJ 116. Pemeriksaan dalam didapatkan pembukaan 3 cm, presentasi kepala, teraba tali pusat dijalan lahir, ketuban (-). Apakah tatalaksana pada pasien diatas?","opts":["Observasi","Rujuk","SC","Pimpin persalinan normal","Induksi"],"ans":1,"why":"Tali pusat teraba di jalan lahir setelah ketuban pecah, DJJ menurun (116) → prolaps tali pusat. Di puskesmas: posisi knee-chest/Trendelenburg, dorong bagian terendah agar tidak menekan tali pusat, lalu RUJUK segera untuk SC.","ref":[28],"tags":["Prolaps tali pusat"],"skdi":"3B","src":"kunci","cards":[{"q":"Prolaps tali pusat di faskes primer?","a":"Knee-chest, tahan bagian terendah, rujuk untuk SC"}]},
{"id":"og1-x09","lat":"pj-obg","ln":9,"lp":3,"stem":"Seorang wanita berusia 35 tahun baru saja menjalani kuretase 4 minggu yang lalu atas indikasi hamil anggur. Saat ini pasien datang untuk control mingguan. Pasien tidak memiliki keluhan selain penurunan berat badan sebanyak 1,5 kilogram semenjak kuretase. Pemeriksaan tanda vital dalam batas normal. Pada pemeriksaan fisik lainnya tidak ditemukan kelainan. Pada pemeriksaan serum beta-hCG didapatkan hasil dengan peningkatan konstan beta-hCG setiap minggunya sejak kuretase. Dokter memikirkan adanya suatu proses keganasan. Dan didapatkan metastasis ke organ genitalia. Stage penyakit tersebut adalah?","opts":["Stage I","Stage II","Stage III","Stage IV","Stage V"],"ans":1,"why":"β-hCG terus naik setelah evakuasi mola → neoplasia trofoblas gestasional. FIGO: I terbatas di uterus; II meluas ke luar uterus tetapi terbatas pada struktur genitalia (adneksa, vagina, ligamen); III metastasis paru; IV metastasis jauh lainnya (otak, hati).","ref":[50],"tags":["Penyakit trofoblas ganas"],"skdi":"2","src":"kunci","cards":[{"q":"FIGO NTG stadium II?","a":"Menyebar ke genitalia (adneksa, vagina)"},{"q":"FIGO NTG stadium III?","a":"Metastasis paru"},{"q":"FIGO NTG stadium IV?","a":"Metastasis jauh lain (otak, hati)"}]},
{"id":"og1-x10","lat":"pj-obg","ln":10,"lp":4,"stem":"Seorang wanita 28 tahun P1A0 sedang berada dalam kala III persalinan dibantu oleh bidan. Saat ini terjadi perdarahan hebat dari jalan lahir. Pasien telah dilakukan manajemen aktif kala III. Plasenta belum kunjung lahir sehingga dilakukan penarikan tali pusat. Pada pemeriksaan fisik dijumpai kontraksi uterus sulit dievaluasi dan teraba massa di vagina. Apakah tatalaksana definitif pada kasus?","opts":["Manual plasenta","Reduksi manual","Kompresi bimanual","Eksplorasi digitalis","Histerektomi"],"ans":1,"why":"Kala III dengan penarikan tali pusat berlebihan sebelum plasenta lepas → fundus tidak teraba, massa di vagina, perdarahan/syok → inversio uteri. Tatalaksana: reposisi/reduksi manual segera (Johnson), lalu uterotonika.","ref":[42,43],"tags":["Inversio uteri"],"skdi":"3B","src":"kunci","cards":[{"q":"Inversio uteri: tatalaksana?","a":"Reposisi manual (Johnson)"}]},
{"id":"og1-x11","lat":"pj-obg","ln":11,"lp":4,"stem":"Perempuan usia 28 tahun G2P0A0 Usia kehamilan 30 minggu datang dengan keluhan kencang-kencang sejak 8 jam sebelum masuk rumah sakit. Kencang-kencang tersebut dirasakan semakin teratur. Gerakan janin masih dirasa normal. Pemeriksaan tanda vital TD 110/70, HR 80, RR 16. DJJ 154. pemeriksaan dalam didapatkan pembukaan serviks 2 cm dengan penipisan 80%, selaput ketuban intak Obat apakah yang diberikan sebagai neuroprotektor pada kasus diatas?","opts":["Dexametason 6mg/12jam IM","Betametason 12mg/48 jam IM","Ampisilin 2 g IV tiap 6 jam","MgSO44gIV dalam 15 menitloading","Nifedipin loading dose 20-30 mg"],"ans":3,"why":"Persalinan preterm < 32 minggu → MgSO₄ sebagai NEUROPROTEKTOR janin (mengurangi risiko palsi serebral): loading 4 g IV dalam 15 menit. Kortikosteroid (deksametason 6 mg/12 jam × 4) untuk pematangan paru; nifedipin untuk tokolisis.","ref":[26],"tags":["Persalinan preterm"],"skdi":"3B","src":"kunci","cards":[{"q":"Neuroproteksi janin < 32 minggu?","a":"MgSO₄ 4 g IV loading"},{"q":"Pematangan paru: deksametason?","a":"6 mg IM tiap 12 jam × 4 dosis"},{"q":"Pematangan paru: betametason?","a":"12 mg IM tiap 24 jam × 2 dosis"}]},
{"id":"og1-x12","lat":"pj-obg","ln":12,"lp":4,"stem":"Seorang wanita usia 28 tahun G2P1A0 usia kehamilan 38 minggu rujukan dari bidan dibawa ke IGD 4 karena persalinan macet. Pasien telah dipimpin mengejan selama 2 jam namun bayi tak kunjung lahir. Pada pemeriksaan fisik didapatkan TTV dbn. Dokter IGD melakukan pemeriksaan dan didapatkan turtle sign (+). Pasien memiliki riwayat DM tidak terkontrol dan taksiran berat janin sebesar 4500 gram. Dokter menyarankan pasien untuk tidur telentang, memfleksikan kedua paha sehingga lutut menjadi sedekat mungkin dengan dada dan merotasikan kedua kaki kearah luar Manuver yang dilakukan tersebut adalah?","opts":["Mc Roberts","Massanti","Rubin","Woods screw","Gaskin all-fours"],"ans":0,"why":"Turtle sign (kepala tertarik kembali ke perineum) pada janin makrosomia ibu DM → distosia bahu. Manuver pertama: McRoberts (hiperfleksi paha ke perut, abduksi-rotasi luar) + tekanan suprapubik.","ref":[34,35],"tags":["Distosia bahu"],"skdi":"3A","src":"kunci","cards":[{"q":"Turtle sign?","a":"Distosia bahu"},{"q":"Manuver pertama distosia bahu?","a":"McRoberts + tekanan suprapubik"}]},
{"id":"og1-x13","lat":"pj-obg","ln":15,"lp":5,"stem":"Seorang wanita usia 24 tahun datang ke poliklinik dengan keluhan nyeri pada payudara kanan saat menyusui. Pasien mengaku beberapa hari yang lalu bayi menggigit putting payudara tersebut. Pemeriksaan tanda vital dalam batas normal. pemeriksaan status lokalis tampak luka lecet pada papilla mammae dan areola mammae dextra, perdarahan (-), kemerahan (-) Apakah tatalaksana kasus diatas?","opts":["Mengoleskan ASI","Hindari menyusu pada payudara yang sakit","Insisi drainase","Antibiotik","Pompa ASI"],"ans":0,"why":"Puting lecet karena perlekatan salah/gigitan, tanpa tanda infeksi → oleskan ASI pada puting (antiseptik & pelembap alami), perbaiki perlekatan, tetap menyusui (mulai dari payudara yang tidak sakit).","ref":[20],"tags":["Puting lecet"],"skdi":"4A","src":"kunci","cards":[{"q":"Tatalaksana puting lecet?","a":"Oles ASI, perbaiki perlekatan, tetap menyusui"}]},
{"id":"og1-x14","lat":"pj-obg","ln":19,"lp":6,"stem":"Seorang ibu muda datang untuk control setelah melahirkan 1 minggu yang lalu. Sang ibu mengeluhkan berat badan bayi menurun jika dibandingkan berat lahirnya. Padahal ia sering menyusui bayinya. Saat ibu tersebut menyusui di poli KIA, bayi nampak tidak nyaman. Dibawah ini adalah posisi dan perlengketan menyusui yang benar, kecuali?","opts":["Perut dan dada bayi menempel pada perut dan dada ibu","Seluruh badan bayi menghadap ke badan ibu, telinga bayi membentuk garis lurus dengan lengan bayi","Bibir bayi tampak mencucu","Punggung bayi tersanggah","Bibir bawah bayi terputar keluar"],"ans":2,"why":"Tanda perlekatan baik: dagu menempel payudara, mulut terbuka lebar, bibir bawah terputar keluar (dower), sebagian besar areola masuk mulut. Posisi baik: badan bayi menghadap ibu, perut menempel, telinga-lengan segaris, tubuh tersangga. Bibir MENCUCU = perlekatan salah.","ref":[20],"tags":["Menyusui"],"skdi":"4A","src":"kunci","cards":[{"q":"Tanda perlekatan menyusui benar?","a":"Mulut terbuka lebar, bibir bawah terputar keluar, dagu menempel"}]},
{"id":"og1-x15","lat":"pj-obg","ln":23,"lp":7,"stem":"Wanita 25 tahun baru melahirkan anak kedua 2 minggu yang lalu akan tetapi bayi meninggal beberapa hari kemudian setelah dilahirkan. Saat ini pasien datang. Bersama suami karena payudara terasa bengkak dan nyeri. Pemeriksaan TD 120/70, HR 83, suhu 37 C. pasien mengatakan ingin stop produksi ASI. Pilihan obat yang dapat menghentikan produksi ASI dibawah ini?","opts":["Progesteron","Pil KB","Bromokriptin","NSAID","Paracetamol"],"ans":2,"why":"Penghentian produksi ASI (misal bayi meninggal) → agonis dopamin (bromokriptin atau kabergolin) yang menekan prolaktin. Kunci: bromokriptin.","ref":[20],"tags":["Supresi laktasi"],"skdi":"3A","src":"kunci","cards":[{"q":"Obat menghentikan produksi ASI?","a":"Agonis dopamin (bromokriptin/kabergolin)"}]},
{"id":"og1-x16","lat":"aipki-obg","ln":1,"lp":2,"stem":"Seorang wanita berusia 24 tahun G1P0A0 usia kehamilan 32 minggu datang ke dokter spesialis kandungan karena kurang merasakan gerakan janinnya sejak 2 hari yang lalu. Pada pemeriksaan fisik didapatkan TTV TD 110/70 HR 89 RR 20 T 37. TFU sesuai usia kehamilan. DJJ 100 x/menit. Pada pemeriksaan KTG didapatkan deselerasi lambat. Apakah penyebab kondisi yang terjadi pada kasus?","opts":["Insufisiensi uteroplasenta","Prolaps tali pusat","Kompresi tali pusat","Kompresi kepala janin","Intrauterine Growth Restriction"],"ans":0,"why":"Deselerasi LAMBAT (late deceleration: penurunan DJJ setelah puncak kontraksi) → insufisiensi uteroplasenta. Deselerasi dini = kompresi kepala; variabel = kompresi tali pusat.","ref":[24,25],"tags":["CTG"],"skdi":"3A","src":"kunci","cards":[{"q":"Deselerasi dini?","a":"Kompresi kepala janin"},{"q":"Deselerasi variabel?","a":"Kompresi tali pusat"},{"q":"Deselerasi lambat?","a":"Insufisiensi uteroplasenta"}]},
{"id":"og1-x17","lat":"aipki-obg","ln":2,"lp":2,"stem":"Wanita 27 tahun, G2P1A0 UK 38 minggu datang dengan keluhan seperti ingin melahirkan. Pada pemeriksaan dalam pembukaan 6 cm, kontraksi 4x selama 40 detik, DJJ 150 kali/menit. Ketuban (+). Setelah dilakukan observasi kemajuan persalinan pembukaan 10 cm, his 5x selama 60 detik, DJJ 135 kali/menit, ketuban (-), Kepala janin tampak di vulva . Lalu dilakukan pimpim persalinan. Apakah diagnosis yang tepat?","opts":["Inpartu kala I fase aktif","Inpartu kala I fase laten","Kala 1 fase laten memanjang","Inpartu kala II","Kala 2 memanjang"],"ans":3,"why":"Pembukaan lengkap (10 cm), kepala tampak di vulva, ibu dipimpin mengejan → kala II (pembukaan lengkap sampai bayi lahir).","ref":[16,17],"tags":["Kala persalinan"],"skdi":"4A","src":"kunci","cards":[{"q":"Kala II dimulai saat…?","a":"Pembukaan lengkap (10 cm)"},{"q":"Kala I fase aktif dimulai pembukaan…?","a":"≥ 4 cm (pedoman lama) / ≥ 6 cm (WHO baru)"}]},
{"id":"og1-x18","lat":"aipki-obg","ln":4,"lp":2,"stem":"Wanita usia 29 tahun, G2P1A0 usia kehamilan 39-40 minggu datang ke IGD dengan perut sudah mulai mulas-mulas. Tidak ada cairan yang keluar dari jalan lahir maupun lender darah.Pemeriksaan lebih lanjut ditemukan kontraksi 1 kali durasi 10 detik pembukaan 3 cm, mulut,, dengan dagu mengarah ke posterior. Ketuban (+) Hodge I. Apakah tindakan yang dapat dilakukan?","opts":["Persalinan pervaginam","Observasi","SC","Versi luar","Manuver lovset"],"ans":2,"why":"Presentasi muka (teraba mulut, dagu) dengan dagu ke POSTERIOR (mentoposterior) → tidak dapat lahir pervaginam karena kepala tidak bisa ekstensi lebih lanjut → SC. Mentoanterior dapat lahir pervaginam.","ref":[37,38],"tags":["Presentasi muka"],"skdi":"3A","src":"kunci","cards":[{"q":"Presentasi muka mentoposterior: tindakan?","a":"Seksio sesarea"},{"q":"Presentasi muka mentoanterior?","a":"Dapat lahir pervaginam"}]},
{"id":"og1-x19","lat":"aipki-obg","ln":5,"lp":2,"stem":"Seorang wanita 25 tahun baru saja melahirkan anak pertamanya di Puskesmas. Anak lahir dengan usia kehamilan 38 minggu, BBL 3100 gram. Setelah 30 menit pasca anak lahir, plasenta tidak kunjung lahir. Dokter telah melakukan masase uterus, injeksi oksitosin 10 IU IM serta peregangan tali pusat terkendali, namun plasenta tidak kunjung lahir. Apakah diagnosis dan tatalaksana yang tepat?","opts":["Ruptur uteri, Histerektomi","Retensio plasenta, Masase uterus","Inpartu kala III, Penarikan tali pusat terkendali","Retensio plasenta, Manual plasenta","Sisa plasenta, Injeksi ergotamin"],"ans":3,"why":"Plasenta tidak lahir > 30 menit setelah bayi lahir walau MAK III (oksitosin, PTT, masase) → retensio plasenta → manual plasenta.","ref":[42],"tags":["Retensio plasenta"],"skdi":"4A","src":"kunci","cards":[{"q":"Retensio plasenta: definisi?","a":"Plasenta belum lahir > 30 menit setelah bayi lahir"}]},
{"id":"og1-x20","lat":"aipki-obg","ln":6,"lp":3,"stem":"Seorang wanita usia 30 tahun, G4P3A0 UK 38 minggu, dibawa ke IGD rumah sakit karena mengeluarkan lendir darah yang diikuti dengan keluhan mulas yang makin sering sejak 1 jam yang lalu. Pasien mengaku memiliki riwayat DM gestasional pada kehamilan ini. Tanda-tanda vital TD 120/70, nadi 106. Pada pemeriksaan dalam didapatkan pembukaan lengkap, kepala di hodge IV, ketuban (-). Saat dipimpin persalinan, kepala bayi sudah keluar, namun bahu belum dapat dilahirkan. Kemudian dokter melakukan manuver wood’s screw Apakah maksud manuver yang dilakukan diatas?","opts":["Fleksi lutut dan panggul hingga menyentuh abdomen/dada","Penekanan suprapubic untuk membebaskan bahu anterior","Memasukkan jari dan menekan bahu posterior kearah dada bayi untuk membebaskan bahu anterior","Memasukkan jari dan menekan bahu posterior ke arah punggung bayi","Posisi ibu dalam posisi merangkak"],"ans":3,"why":"Manuver Woods corkscrew: tekanan pada permukaan ANTERIOR bahu posterior untuk memutar bahu 180° (ke arah punggung bayi) seperti sekrup. Rubin II: tekan permukaan posterior bahu anterior ke arah dada bayi. McRoberts: fleksi paha ke perut; Gaskin: posisi merangkak.","ref":[34,35],"tags":["Distosia bahu"],"skdi":"3A","src":"kunci","cards":[{"q":"Manuver Woods corkscrew?","a":"Putar bahu posterior 180° (tekan sisi anteriornya)"},{"q":"Manuver Rubin II?","a":"Tekan bahu anterior ke arah dada bayi"},{"q":"Manuver Gaskin?","a":"Ibu posisi merangkak (all-fours)"}]},
{"id":"og1-x21","lat":"aipki-obg","ln":7,"lp":3,"stem":"Wanita usia 32 tahun, G2P1A0, datang ke IGD dengan keluhan kencang-kencang sejak 6 jam yang lalu. Pasien mengaku keluar cairan jernih dan lender darah. Pemeriksaan tanda vital dalam batas normal. dilakukan pemeriksaan dalam dan didapatkan pembukaan lengkap. Saat ini sedang menjalani persalinan. Tampak bahu bayi tersangkut dan 2 dokter melakukan episiotomi untuk membebaskannya. Walaupun demikian, terjadi robekan pada perineum pasien yang mencapai sfingter eksterna dan interna. Epitel anus tidak terlibat. Apakah diagnosis kasus diatas?","opts":["Ruptur perineum grade I","Ruptur perineum grade II","Ruptur perineum grade IIIA","Ruptur perineum grade IIIB","Ruptur perineum grade IIIC"],"ans":4,"why":"Derajat ruptur perineum: I mukosa vagina/kulit; II otot perineum; IIIA sfingter ani eksterna < 50%; IIIB > 50%; IIIC sfingter eksterna DAN interna; IV sampai mukosa/epitel anus-rektum.","ref":[42],"tags":["Ruptur perineum"],"skdi":"3A","src":"kunci","cards":[{"q":"Ruptur perineum IIIC?","a":"Sfingter ani eksterna + interna robek"},{"q":"Ruptur perineum derajat IV?","a":"Sampai mukosa rektum"},{"q":"Ruptur perineum derajat II?","a":"Mengenai otot perineum"}]},
{"id":"og1-x22","lat":"aipki-obg","ln":8,"lp":3,"stem":"Seorang wanita berusia 32 tahun G4P3A0 usia kehamilan 38 minggu datang dengan keadaan mulas-mulas sejak 8 jam. Keluar cairan bening dan lender darah. Pemeriksaan didapatkan his adekuat, teraba lunak pada bagian fundus uteri, punggung kanan, DJJ 144x/menit, kepala sudah masuk PAP. Dokter sudah memimpin persalinan selama 30 menit namun ibu kelelahan. Kepala bayi ada di Hodge IV, presentasi muka . Apakah tatalaksana yang dapat diberikan?","opts":["Misoprostol","Oksitoksin","Forceps","Vakum","SC"],"ans":2,"why":"Kala II memanjang/ibu kelelahan dengan presentasi MUKA di Hodge IV → bantu dengan forsep. Vakum kontraindikasi pada presentasi muka (trauma wajah).","ref":[32],"tags":["Presentasi muka","Ekstraksi forsep"],"skdi":"2","src":"kunci","cards":[{"q":"Kontraindikasi ekstraksi vakum?","a":"Presentasi muka/dahi, prematur < 34 mg"}]},
{"id":"og1-x23","lat":"aipki-obg","ln":9,"lp":3,"stem":"Seorang wanita G2P1A0 uk 38 minggu, datang dengan keluhan kenceng-kenceng semakin kuat sejak 2 jam SMRS yang lalu. Keluhan disertai lender darah. Pada pemeriksaan fisik didapatkan tekanan darah 100/80, denyut nadi 100, frekuensi napas 16 dan suhu 37, . His 10.3.40”. VT: pembukaan 4 cm. Setelah dilakukan observasi 4 jam kemudian His 10.2.20”. Pembukaan 7 cm, kepala hodge 1-2 Apakah diagnosa kasus diatas?","opts":["Hipertoni uteri","Inersia uteri primer","Inersia uteri sekunder","Braxton hicks","Fase laten memanjang"],"ans":2,"why":"His awalnya adekuat (3×/10 menit, 40 detik) lalu MELEMAH (2×/10 menit, 20 detik) di fase aktif → inersia uteri SEKUNDER. Primer: his lemah sejak awal persalinan.","ref":[33],"tags":["Inersia uteri"],"skdi":"3A","src":"kunci","cards":[{"q":"Inersia uteri sekunder?","a":"His awalnya baik lalu melemah"}]},
{"id":"og1-x24","lat":"aipki-obg","ln":11,"lp":4,"stem":"Seorang wanita berusia 32 tahun datang ke RS dengan G3P2A0 UK 37 minggu merasa mulas sejak 2 jam ini. Keluar cairan jernih disertai dengan lender darah. Pada saat dilakukan vaginal touche pembukaan 10 cm dan teraba dua kaki dan tidak teraba bokong. Pemeriksaan DJJ : 150x/menit Apakah diagnose kasus diatas?","opts":["Kneeling breech","Complete breech","Frank breech","Incomplate breech","Bokong murni"],"ans":3,"why":"Teraba kedua kaki tanpa bokong → presentasi bokong tidak sempurna (incomplete/footling breech). Frank (bokong murni): bokong saja, tungkai ekstensi ke kepala. Complete: bokong + kedua kaki terlipat.","ref":[37],"tags":["Presentasi bokong"],"skdi":"3A","src":"kunci","cards":[{"q":"Frank breech?","a":"Bokong murni (tungkai lurus ke atas)"},{"q":"Complete breech?","a":"Bokong + kedua kaki terlipat"},{"q":"Footling breech?","a":"Kaki sebagai bagian terendah"}]},
{"id":"og1-x25","lat":"aipki-obg","ln":12,"lp":4,"stem":"Seorang wanita usia 22 tahun G1P0A0 datang untuk memeriksakan kehamilan. Pasien tidak ingat HPHT, namun pasien merasa terakhir haid 2 sekitar sebulan yang lalu. Pemeriksaan plano test (+). Oleh dokter akan dilakukan pemeriksaan USG pada pasien. Apakah perhitungan yang paling akurat dilkaukan pada masa kehamilan saat ini?","opts":["Gestasional sac","Humerus length","Crown-rump length (CRL)","Biparietal diameter (BPD)","Femur length"],"ans":0,"why":"Haid terakhir ± 1 bulan → kehamilan sangat dini (± 4–6 minggu): yang terlihat baru kantong gestasi (GS), sehingga biometri paling akurat saat ini = diameter gestational sac. CRL paling akurat pada 7–13 minggu; BPD/FL trimester II.","ref":[7],"tags":["Usia kehamilan","USG"],"skdi":"3A","src":"kunci","cards":[{"q":"Biometri paling akurat trimester I (7–13 mg)?","a":"Crown-rump length (CRL)"},{"q":"Biometri usia < 6 minggu?","a":"Diameter gestational sac"}]},
{"id":"og1-x26","lat":"aipki-obg","ln":13,"lp":4,"stem":"Seorang perempuan usia 28 tahun telah melahirkan bayi sehat dan normal di puskesmas, tanda vital ibu normal, saat ini dokter sedang melakukan pemeriksaan pengeluaran plasenta dengan cara meletakkan tangan kiri disertai tekanan pada atas simfisis, tali pusat ditegangkan dengan tangan kanan, bila tali pusat tak tertarik masuk lagi berarti tali pusat telah lepas. Apakah nama metode pengeluaran plasenta yang dimaksud?","opts":["Perasat klein","Perasat kustner","Perasat Strassman","Perasat Duncan","Perasat schultze"],"ans":1,"why":"Perasat KÜSTNER: tangan menekan di atas simfisis sambil tali pusat ditegangkan; bila tali pusat tidak masuk kembali → plasenta sudah lepas. Klein: ibu mengejan, tali pusat tidak masuk lagi setelah mengejan dihentikan. Strassman: ketok fundus, getaran terasa di tali pusat → belum lepas.","ref":[17],"tags":["Kala III","Lepasnya plasenta"],"skdi":"4A","src":"kunci","cards":[{"q":"Perasat Küstner?","a":"Tekan suprasimfisis; tali pusat tidak masuk lagi = plasenta lepas"},{"q":"Perasat Strassman?","a":"Ketok fundus; getaran sampai tali pusat = belum lepas"},{"q":"Perasat Klein?","a":"Ibu mengejan; tali pusat tidak masuk kembali = lepas"}]},
{"id":"og1-x27","lat":"aipki-obg","ln":14,"lp":4,"stem":"Seorang perempuan usia 27 tahun, G2P1A0 Usia Kehamilan 38 minggu, datang dalam keadaaan inpartu. Pada pemeriksaan fisik didapatkan tekanan darah 110/80, denyut nadi 70, frekuensi napas 19 dan suhu 36,6. Pemeriksaan dalam didapatkan pembukaan 7cm, teraba ubun-ubun kecil kearah sakrum Apakah yang terjadi pada pasien diatas?","opts":["Malposisi oksiput lintang","Malposisi oksiput posterior","Letak oblique","Letak transversal","Presentasi wajah"],"ans":1,"why":"Ubun-ubun kecil (oksiput) mengarah ke SAKRUM (belakang) → malposisi oksiput posterior (posisi oksipitoposterior persisten bila menetap).","ref":[37],"tags":["Malposisi"],"skdi":"3A","src":"kunci","cards":[{"q":"UUK ke arah sakrum?","a":"Oksiput posterior"}]},
{"id":"og1-x28","lat":"aipki-obg","ln":15,"lp":5,"stem":"Seorang pasien 32 tahun G2P1A0 usia kehamilan 35 minggu datang ke poli kandungan untuk perencanaan kelahiran. Pemeriksaan tanda vital dalam batas normal. TFU sesuai dengan masa kehamilan. Pada pemeriksaan lanjutan didapati villi plasenta terdapat di dalam myometrium. Apakah diagnosis kasus diatas?","opts":["Plasenta akreta","Plasenta inkreta","Plasenta perkreta","Normal plasenta","Plasenta previa"],"ans":1,"why":"Spektrum plasenta akreta: akreta = vili menempel ke miometrium (tanpa desidua basalis); INKRETA = vili masuk ke dalam miometrium; perkreta = menembus sampai serosa/organ sekitar.","ref":[42,43],"tags":["Plasenta akreta"],"skdi":"2","src":"kunci","cards":[{"q":"Plasenta inkreta?","a":"Vili menembus ke dalam miometrium"},{"q":"Plasenta perkreta?","a":"Vili menembus sampai serosa/organ sekitar"}]},
{"id":"og1-x29","lat":"fk-obgped","ln":1,"lp":3,"stem":"Wanita 23 tahun belum haid sejak 4 bulan, mual muntah (+), tes kehamilan (+). HPHT 8 Desember 2024, haid selama 7 hari. Siklus teratur, selalu mundur 2 hari dari tanggal bulan sebelumnya (siklus 30 hari). Kapankah taksiran tanggal persalinan?","opts":["4 September 2025","6 September 2025","8 September 2025","10 September 2025","12 September 2025"],"ans":4,"why":"Kunci slide pembahasan: 12 September 2025. Rumus Naegele (siklus 28): HPHT + 7 hari − 3 bulan + 1 tahun; siklus lebih panjang → tambahkan (siklus − 28) hari. Dengan HPHT 8 Des 2024 dan siklus 30 hari hasilnya 17 Sep 2025 (bila HPHT dianggap 1 Des: 10 Sep). Kunci perlu dicek.","ref":[7],"tags":["Taksiran persalinan","Naegele"],"skdi":"4A","src":"flag","cards":[{"q":"Rumus Naegele?","a":"HPHT + 7 hari − 3 bulan + 1 tahun"},{"q":"Naegele siklus > 28 hari?","a":"Tambah (siklus − 28) hari"}],"xp":[4,5]},
{"id":"og1-x30","lat":"fk-obgped","ln":2,"lp":8,"stem":"Wanita 29 tahun G2P1A0 UK 38 minggu dengan nyeri perut makin sering dan kuat sejak 2 jam, lendir darah (+). TFU 33 cm, DJJ 145, his 3×/10 menit (45 detik), kepala sudah masuk PAP. VT pembukaan 6 cm; dievaluasi ulang 4 jam kemudian pembukaan 9 cm. Apakah diagnosis yang tepat?","opts":["Prolonged latent phase","Prolonged active phase","Arrest of dilatation","Protracted descent","Arrest of descent"],"ans":1,"why":"Fase aktif: dilatasi 6 → 9 cm dalam 4 jam (< 1 cm/jam, multipara normal ≥ 1,5 cm/jam) → fase aktif memanjang (protracted/prolonged active phase). Arrest = tidak ada kemajuan ≥ 2 jam (pedoman lama) dengan his adekuat.","ref":[29,30],"tags":["Partus lama"],"skdi":"3A","src":"kunci","cards":[{"q":"Fase aktif memanjang?","a":"Dilatasi < 1 cm/jam (primi) / < 1,5 cm/jam (multi)"},{"q":"Arrest of dilatation?","a":"Tidak ada kemajuan pembukaan ≥ 2 jam"}],"xp":[9,10]},
{"id":"og1-x31","lat":"fk-obgped","ln":3,"lp":14,"stem":"Wanita 31 tahun G3P2A0 UK 38 minggu ingin melahirkan, his jarang, pembukaan 3 cm. Pemeriksaan dalam: teraba tali pusat (+), selaput ketuban (−), mekonium (+); janin letak memanjang dengan bokong sebagai bagian terendah. Apakah posisi ibu yang tepat untuk mengatasi kegawatan?","opts":["Litotomi","Trendelenburg","Prone","Dorsal supine","Fowler"],"ans":1,"why":"Prolaps tali pusat → kurangi tekanan bagian terendah janin pada tali pusat dengan posisi Trendelenburg atau knee-chest, tangan menahan bagian terendah, lalu seksio sesarea segera.","ref":[28],"tags":["Prolaps tali pusat"],"skdi":"3B","src":"kunci","cards":[{"q":"Posisi ibu pada prolaps tali pusat?","a":"Trendelenburg / knee-chest"}],"xp":[15,16]},
{"id":"og1-x32","lat":"fk-obgped","ln":6,"lp":31,"stem":"Perempuan 28 tahun G2P1A0 hamil ± 10 minggu dengan perdarahan pervaginam dan nyeri perut bawah sejak 6 jam; sebelumnya keluar jaringan namun perdarahan masih berlangsung. Tampak lemas, TD 100/60, HR 106. OUE terbuka, perdarahan aktif (+). Apakah tatalaksana yang tepat?","opts":["Pertahankan kehamilan","Kuretase","Tunggu pengeluaran konsepsi spontan","Tidak perlu evakuasi","Resusitasi cairan saja"],"ans":1,"why":"Sudah keluar sebagian jaringan, OUE terbuka, perdarahan aktif → abortus inkomplit → evakuasi sisa konsepsi (kuretase/AVM; usia < 12–14 minggu) disertai stabilisasi hemodinamik.","ref":[48,49],"tags":["Abortus inkomplit"],"skdi":"3B","src":"kunci","cards":[{"q":"Abortus inkomplit: tatalaksana?","a":"Evakuasi sisa konsepsi (kuretase/AVM)"}],"xp":[32,33]},
{"id":"og1-x33","lat":"fk-obgped","ln":7,"lp":36,"stem":"Wanita G2P1A0 ANC di bidan; anak pertama lahir spontan 3 tahun lalu (BBL 2800 g). Sebelumnya memakai pil KB kombinasi, tanpa riwayat DM atau hipertensi. Fundus uteri teraba 2 jari di bawah pusat. Berapa perkiraan usia kehamilan?","opts":["12 minggu","11 minggu","24 minggu","18 minggu","22 minggu"],"ans":3,"why":"Perkiraan usia kehamilan dari TFU (Leopold): 12 mg = 3 jari di atas simfisis; 16 mg = pertengahan simfisis–pusat; 20 mg = 2–3 jari di bawah pusat; 24 mg = setinggi pusat. Kunci slide: 18 minggu (catatan dosen menulis ± 20 minggu).","ref":[7],"tags":["TFU","Usia kehamilan"],"skdi":"4A","src":"kunci","cards":[{"q":"TFU setinggi pusat ≈ UK?","a":"24 minggu"},{"q":"TFU pertengahan simfisis–pusat ≈ UK?","a":"16 minggu"},{"q":"TFU setinggi prosesus xifoideus ≈ UK?","a":"36 minggu"}],"xp":[37,38]},
{"id":"og1-x34","lat":"fk-obgped","ln":8,"lp":39,"stem":"Perempuan 36 tahun G2P1A0 dengan perdarahan pervaginam merah segar 4 hari, tidak nyeri, disertai mual muntah hebat. Belum merasakan gerak janin padahal UK 14 minggu berdasar HPHT; TFU setara kehamilan 20 minggu. USG: snowstorm appearance. Apakah diagnosis yang tepat?","opts":["Solusio plasenta","Abortus inkomplit","Ruptur uteri","Mola hidatidosa","Plasenta previa"],"ans":3,"why":"Perdarahan kehamilan muda + uterus lebih besar dari usia kehamilan + hiperemesis + tanpa gerak janin + USG snowstorm/honeycomb → mola hidatidosa.","ref":[50],"tags":["Mola hidatidosa"],"skdi":"3B","src":"kunci","cards":[],"xp":[40,41]}
]});
